from collections import deque

def cells(grid):
    """(height, width) of the grid."""
    return len(grid), len(grid[0])

def border_reachable(grid, bg):
    """Set of background cells connected (4-neighbor) to the grid border."""
    h, w = cells(grid)
    seen = {(i, j) for i in range(h) for j in (0, w - 1) if grid[i][j] == bg}
    seen |= {(i, j) for j in range(w) for i in (0, h - 1) if grid[i][j] == bg}
    q = deque(seen)
    while q:
        i, j = q.popleft()
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            a, b = i + di, j + dj
            if 0 <= a < h and 0 <= b < w and grid[a][b] == bg and (a, b) not in seen:
                seen.add((a, b)); q.append((a, b))
    return seen

def fill_enclosed(grid, fill=4):
    """Recolor every background (most common) cell not reachable from the border to fill."""
    from collections import Counter
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    reach = border_reachable(grid, bg)
    h, w = cells(grid)
    return [[fill if grid[i][j] == bg and (i, j) not in reach else v
             for j, v in enumerate(row)] for i, row in enumerate(grid)]
